sys_script.script:
(function executeRule(current, previous) {

    // Run only when status or technician has changed.
    var statusChanged = current.status.changes();
    var technicianChanged = current.technician.changes();

    if (!statusChanged && !technicianChanged) {
        return;
    }

    if (current.request.nil()) {
        return;
    }

    var status = current.getDisplayValue('status');

    // Get the related Requested Item.
    var ritm = current.request.getRefRecord();

    if (!ritm || !ritm.isValidRecord()) {
        gs.error('Lab sync: Related Requested Item not found.');
        return;
    }

    var ritmChanged = false;

    // ------------------------------------------------
    // 1. SYNC REQUEST STATE WITH LAB RESULT STATUS
    // ------------------------------------------------

    if (statusChanged) {

        var ritmState = '';

        if (status == 'Requested') {
            ritmState = '1';
        } else if (
            status == 'Scheduled' ||
            status == 'Sample Collection' ||
            status == 'Sample Received' ||
            status == 'Testing In Progress' ||
            status == 'Result Entered' ||
            status == 'Result Verified'
        ) {
            ritmState = '2';
        } else if (
            status == 'Report Published' ||
            status == 'Patient Notified'
        ) {
            ritmState = '3';
        }

        if (ritmState) {
            ritm.setValue('state', ritmState);
            ritmChanged = true;
        }
    }

    // ------------------------------------------------
    // 2. DYNAMIC ASSIGNMENT GROUP BASED ON HOSPITAL
    // ------------------------------------------------

    if (statusChanged &&
        previous.getValue('status') == '1') {

        var hospitalId = current.getValue('hospital');

        if (hospitalId) {

            // Get the hospital record.
            var hospital = current.hospital.getRefRecord();

            if (hospital && hospital.isValidRecord()) {

                var hospitalName = hospital.getValue('name');

                // Construct the group name dynamically.
                var groupName = hospitalName + ' - Lab Staff';

                var group = new GlideRecord('sys_user_group');
                group.addQuery('name', groupName);
                group.setLimit(1);
                group.query();

                if (group.next()) {

                    ritm.setValue(
                        'assignment_group',
                        group.getUniqueValue()
                    );

                    ritmChanged = true;

                } else {

                    gs.error(
                        'Lab sync: Lab Staff group not found: ' +
                        groupName
                    );
                }

            } else {

                gs.error(
                    'Lab sync: Hospital record not found: ' +
                    hospitalId
                );
            }

        } else {

            gs.error(
                'Lab sync: Hospital is empty on Lab Test Result.'
            );
        }
    }


    // ------------------------------------------------
    // 3. SYNC TECHNICIAN TO RITM ASSIGNED TO
    // ------------------------------------------------

    if (technicianChanged) {

        if (!current.technician.nil()) {

            var technician = new GlideRecord(
                'x_2223823_apollo_0_staff'
            );

            if (technician.get(current.getValue('technician'))) {

                var technicianUser = technician.getValue('user');

                if (technicianUser) {
                    ritm.setValue('assigned_to', technicianUser);
                    ritmChanged = true;
                } else {
                    gs.error(
                        'Lab sync: Selected Technician has no User linked.'
                    );
                }

            } else {
                gs.error(
                    'Lab sync: Selected Technician Staff record not found.'
                );
            }

        } else {
            // Clear Assigned to if the Technician is cleared.
            ritm.setValue('assigned_to', '');
            ritmChanged = true;
        }
    }

    // ------------------------------------------------
    // 4. UPDATE REQUESTED ITEM ONCE
    // ------------------------------------------------

    if (ritmChanged) {
        ritm.update();
    }

})(current, previous);
